def transform(g):
    h=len(g); w=len(g[0])
    out=[row[:] for row in g]
    seen=[[False]*w for _ in range(h)]
    blocks=[]
    for i in range(h-1):
        for j in range(w-1):
            if g[i][j]==2 and g[i][j+1]==2 and g[i+1][j]==2 and g[i+1][j+1]==2 and not seen[i][j]:
                for a in range(i,i+2):
                    for b in range(j,j+2): seen[a][b]=True
                blocks.append((i,j))
    blocks.sort(key=lambda b:(b[1],b[0]))
    for r,(i,j) in enumerate(reversed(blocks)):
        if r%2==0:
            for a in range(i,i+2):
                for b in range(j,j+2): out[a][b]=8
    return out
